contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // depositAmount: amount to deposit into c by this test contract
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // observe contract balance before
        uint beforeContractBalance = address(c).balance;

        // perform deposit into c
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // After deposit, the contract C's balance must have increased by depositAmount
        uint afterDepositContractBalance = address(c).balance;

        // We cannot read the internal mapping credit directly (it's not public), but we can infer the credited amount
        // as the increase in C's balance attributable to this contract compared to before. For a fresh C and single caller
        // this is the deposited amount. Record inferred credited amount as the change in contract balance so far.
        uint inferredCredited = afterDepositContractBalance - beforeContractBalance;

        // attempt withdrawAll and record whether it reverted
        bool succeeded;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            succeeded = false;
        } else {
            succeeded = true;
        }

        // observe contract balance after withdraw attempt
        uint afterContractBalance = address(c).balance;

        // General rule: If withdrawAll succeeded, then C's balance decreased by exactly the inferred credited amount.
        // (This implies the caller received that amount and C's internal credit for the caller was cleared.)
        assert(!succeeded || (succeeded && afterDepositContractBalance == afterContractBalance + inferredCredited));
    }

    receive() external payable {}
}

